use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_str = input.as_str().unwrap();
    let mut output_str = String::new();
    for c in input_str.chars() {
        if c.is_alphabetic() {
            let is_uppercase = c.is_uppercase();
            let base = if is_uppercase { 65 } else { 97 };
            let offset = if is_uppercase { 32 } else { 97 };
            let char = c.to_ascii_lowercase();
            let new_char = char as u8 - offset;
            output_str.push((new_char as char).to_string());
        } else {
            output_str.push(c);
        }
    }
    Value::String(output_str)
}
